   222→    function normalizeZip(raw) {
   223→      var z = raw.trim().toUpperCase();
   224→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
   225→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
   226→      return z;
   227→    }
