   250→            sessionStorage.setItem('zcc:zip', zip);
   251→            sessionStorage.setItem('zcc:shop', SHOP);
   252→            // Fire custom event for other scripts to listen to
   253→            window.dispatchEvent(new CustomEvent('zcc:validated', {
   254→              detail: { valid: data.allowed, zip: zip }
   255→            }));
   256→          } catch(e) { /* sessionStorage may be unavailable */ }
   257→
   258→          if (data.allowed) {
   259→            var html = '<div class="zcc-result ok">' + esc(data.message);
   260→            if (cfg.showEta && data.eta) {
   261→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   262→            }
   263→            if (cfg.showZone && data.zone) {
   264→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   265→            }
   266→            if (cfg.showDeliveryDays && data.daysOfWeek) {
   267→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
   268→              html += '<div class="zcc-meta zcc-days">Delivers: ' + esc(days) + '</div>';
   269→            }
   270→            if (cfg.showCutoffTime && data.cutoffTime) {
   271→              var parts = data.cutoffTime.split(':');
   272→              var hr = parseInt(parts[0], 10);
   273→              var min = parts[1] || '00';
   274→              var ampm = hr >= 12 ? 'PM' : 'AM';
   275→              var hr12 = hr % 12 || 12;
   276→              html += '<div class="zcc-meta zcc-cutoff">Order by ' + hr12 + ':' + min + ' ' + ampm + ' for same-day delivery</div>';
   277→            }
   278→            if (data.codAvailable === true) {
   279→              html += '<div class="zcc-cod zcc-cod--available">\u2713 Cash on Delivery Available</div>';
   280→            } else if (data.codAvailable === false) {
   281→              html += '<div class="zcc-cod zcc-cod--unavailable">\u2717 COD Not Available</div>';
   282→            }
   283→            if (data.returnPolicy) {
   284→              html += '<div class="zcc-return-policy">\u21a9 ' + esc(data.returnPolicy) + '</div>';
   285→            }
   286→            html += "</div>";
   287→            res.innerHTML = html;
   288→          } else {
   289→            var html = '<div class="zcc-result fail">' + esc(data.message);
   290→            if (cfg.showWaitlistOnFailure) {
   291→              html +=
   292→                '<div class="zcc-wl">' +
   293→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
   294→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
   295→                "</div>";
   296→            }
   297→            html += "</div>";
   298→            res.innerHTML = html;
   299→
