export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session, admin } = await authenticate.admin(request);
  const shop = session.shop;

  let config = await db.widgetConfig.findUnique({ where: { shop } });

  if (!config) {
    config = await db.widgetConfig.create({ data: { shop } });
  }

  // Fetch the active (MAIN) theme so we can build a precise deep-link
  // into the Theme Editor's App Embeds panel.
  let activeThemeName: string | null = null;
  let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
  let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;

  try {
    const themesResponse = await admin.graphql(`
      query GetActiveTheme {
        themes(first: 5, roles: [MAIN]) {
          nodes {
            id
            name
            role
          }
        }
      }
    `);
    const themesData = (await themesResponse.json()) as {
      data: {
        themes: {
          nodes: { id: string; name: string; role: string }[];
        };
      };
    };
    const mainTheme = themesData.data?.themes?.nodes?.[0];
    if (mainTheme) {
      // Extract numeric ID from GID like "gid://shopify/OnlineStoreTheme/123456"
      const numericId = mainTheme.id.split("/").pop();
      activeThemeName = mainTheme.name;
      themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
      // ?context=apps opens the App Embeds tab directly
      themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;
    }
  } catch {
    // Non-fatal — fall back to generic theme editor URL
  }

  return { config, themeEditorUrl, themeEditorAppEmbedsUrl, activeThemeName };
};

